        raise ValueError("Inputs must be two-dimensional")
    if arr.size == 0:
        raise ValueError("Inputs must not be empty")
    if not np.all(np.isfinite(arr)):
        raise ValueError("Inputs must be finite")
    if np.any(arr > 0):
        raise ValueError("Inputs must be nonpositive")
# Check shapes
shape = logp_with_result.shape
if logp_call_only.shape != shape or logp_no_call.shape != shape:
    raise ValueError("Input shapes must match")
# Validate threshold
if isinstance(tau_filter, bool):
    raise ValueError("Invalid threshold: Boolean")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("Threshold must be finite and nonnegative")

# Compute margins
improvement_no_call = logp_with_result - logp_no_call
improvement_call_only = logp_with_result - logp_call_only
avg_no_call = np.mean(improvement_no_call, axis=1)
avg_call_only = np.mean(improvement_call_only, axis=1)
margins = np.minimum(avg_no_call, avg_call_only)
keep_mask = margins > tau_filter
return keep_mask, margins
